<template><AdminLayout><div class="container mx-auto px-2 md:px-6 py-6"><div class="flex flex-col md:flex-row md:justify-between gap-3 mb-6"><div><h1 class="text-3xl font-medium text-gray-700">Almacenes</h1><p class="text-sm text-gray-500">Almacenes vinculados a cada sede</p></div><button @click="open()" class="bg-blue-600 text-white px-4 py-2 rounded-lg"><i class="pi pi-plus mr-2"/>Nuevo almacén</button></div>
<div class="bg-white rounded-lg shadow p-4 mb-4 flex flex-col md:flex-row gap-3"><input v-model="search" @input="load" placeholder="Buscar almacén" class="border rounded px-3 py-2 flex-1"><select v-model="branchId" @change="load" class="border rounded px-3 py-2"><option value="">Todas las sedes</option><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></div>
<div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4"><article v-for="w in items" :key="w.id" class="bg-white rounded-lg shadow p-5"><div class="flex justify-between"><div><div class="font-mono text-xs text-gray-500">{{w.code}}</div><h2 class="font-bold text-lg">{{w.name}}</h2><p class="text-sm text-gray-500">{{w.branch?.name}}</p></div><span v-if="w.is_default" class="h-fit bg-blue-100 text-blue-700 px-2 py-1 text-xs rounded-full">Predeterminado</span></div><div class="grid grid-cols-2 gap-2 my-4 text-center"><div class="bg-gray-50 rounded p-2"><b>{{w.total_stock||0}}</b><div class="text-xs text-gray-500">unidades</div></div><div class="bg-gray-50 rounded p-2"><b>{{w.inventories_count}}</b><div class="text-xs text-gray-500">productos</div></div></div><div class="flex justify-between"><span :class="w.is_active?'text-green-600':'text-gray-500'">{{w.is_active?'Activo':'Inactivo'}}</span><div><button @click="open(w)" class="text-blue-600 mr-3"><i class="pi pi-pencil"/></button><button @click="toggle(w)" :class="w.is_active?'text-red-600':'text-green-600'"><i :class="w.is_active?'pi pi-ban':'pi pi-check-circle'"/></button></div></div></article><div v-if="!items.length" class="bg-white rounded shadow p-8 text-gray-500">No se encontraron almacenes.</div></div>
<div v-if="modal" class="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4"><form @submit.prevent="save" class="bg-white rounded-lg w-full max-w-xl p-6"><h2 class="text-xl font-bold mb-4">{{form.id?'Editar':'Nuevo'}} almacén</h2><div class="grid md:grid-cols-2 gap-4"><label>Sede<select v-model="form.branch_id" required class="block w-full border rounded p-2 mt-1"><option disabled value="">Seleccione</option><option v-for="b in branches.filter(x=>x.is_active)" :value="b.id">{{b.name}}</option></select></label><label>Código<input v-model="form.code" required class="block w-full border rounded p-2 mt-1"></label><label class="md:col-span-2">Nombre<input v-model="form.name" required class="block w-full border rounded p-2 mt-1"></label><label class="md:col-span-2">Dirección<input v-model="form.address" class="block w-full border rounded p-2 mt-1"></label><label class="flex items-center gap-2"><input v-model="form.is_default" type="checkbox">Almacén predeterminado</label><label class="flex items-center gap-2"><input v-model="form.is_active" type="checkbox">Activo</label></div><div class="flex justify-end gap-3 mt-5"><button type="button" @click="modal=false" class="px-4 py-2 bg-gray-200 rounded">Cancelar</button><button :disabled="saving" class="px-4 py-2 bg-blue-600 text-white rounded">Guardar</button></div></form></div>
</div></AdminLayout></template>
<script setup>import AdminLayout from '@/layouts/AdminLayout.vue';import api from '@/api';import {ref,onMounted}from'vue';import{useToast}from'primevue/usetoast';import{useConfirm}from'primevue/useconfirm';const toast=useToast(),confirm=useConfirm(),items=ref([]),branches=ref([]),search=ref(''),branchId=ref(''),modal=ref(false),saving=ref(false),form=ref({});let timer;
const load=()=>{clearTimeout(timer);timer=setTimeout(async()=>{try{items.value=(await api.get('/admin/warehouses',{params:{search:search.value,branch_id:branchId.value}})).data.data}catch(e){toast.add({severity:'error',summary:'Error',detail:'No se pudieron cargar los almacenes',life:4000})}},200)};const loadBranches=async()=>branches.value=(await api.get('/admin/branches')).data.data;
const open=(x=null)=>{form.value=x?{...x}:{branch_id:'',code:'',name:'',address:'',description:'',is_default:false,is_active:true};modal.value=true};const save=async()=>{saving.value=true;try{form.value.id?await api.put(`/admin/warehouses/${form.value.id}`,form.value):await api.post('/admin/warehouses',form.value);modal.value=false;toast.add({severity:'success',summary:'Almacén guardado',life:2500});load()}catch(e){toast.add({severity:'error',summary:'No se pudo guardar',detail:e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0],life:5000})}finally{saving.value=false}};const toggle=w=>confirm.require({message:`¿${w.is_active?'Desactivar':'Activar'} ${w.name}?`,header:'Confirmar',accept:async()=>{try{await api.patch(`/admin/warehouses/${w.id}/status`,{is_active:!w.is_active});load()}catch(e){toast.add({severity:'warn',summary:'Operación rechazada',detail:e.response?.data?.message,life:5000})}}});onMounted(()=>{loadBranches();load()});</script>
